create or replace function public.toolbox_issues_storage_access(p_workspace_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.toolbox_issues_has_access(p_workspace_id) $$; create or replace function public.toolbox_issues_register_attachment(p_workspace_id uuid,p_issue_id text,p_name text,p_mime_type text,p_size_bytes bigint,p_storage_path text) returns jsonb language plpgsql security definer set search_path='' as $$ declare a public.toolbox_issue_attachments%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; if p_size_bytes<1 or p_size_bytes>52428800 then raise exception 'attachment size invalid' using errcode='22023'; end if; if split_part(p_storage_path,'/',1)<>p_workspace_id::text or split_part(p_storage_path,'/',2)<>p_issue_id then raise exception 'attachment path scope invalid' using errcode='22023'; end if; if not exists(select 1 from public.toolbox_issues where workspace_id=p_workspace_id and id=p_issue_id::bigint and archived_at is null) then raise exception 'Issue not found' using errcode='P0002'; end if; insert into public.toolbox_issue_attachments(workspace_id,issue_id,storage_path,name,mime_type,size_bytes,creator_user_id) values(p_workspace_id,p_issue_id::bigint,p_storage_path,left(p_name,300),left(p_mime_type,200),p_size_bytes,(select auth.uid())) returning * into a; update public.toolbox_issues set updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_issue_id::bigint; return private.toolbox_issue_asset_json(a); end $$; revoke execute on function public.toolbox_issues_storage_access(uuid),public.toolbox_issues_register_attachment(uuid,text,text,text,bigint,text) from public,anon; grant execute on function public.toolbox_issues_storage_access(uuid),public.toolbox_issues_register_attachment(uuid,text,text,text,bigint,text) to authenticated; insert into storage.buckets(id,name,public,file_size_limit) values('toolbox-issues-attachments','toolbox-issues-attachments',false,52428800) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit; drop policy if exists "toolbox issues attachment read" on storage.objects; drop policy if exists "toolbox issues attachment insert" on storage.objects; drop policy if exists "toolbox issues attachment delete" on storage.objects; create policy "toolbox issues attachment read" on storage.objects for select to authenticated using(bucket_id='toolbox-issues-attachments' and public.toolbox_issues_storage_access(((storage.foldername(name))[1])::uuid)); create policy "toolbox issues attachment insert" on storage.objects for insert to authenticated with check(bucket_id='toolbox-issues-attachments' and public.toolbox_issues_storage_access(((storage.foldername(name))[1])::uuid)); create policy "toolbox issues attachment delete" on storage.objects for delete to authenticated using(bucket_id='toolbox-issues-attachments' and public.toolbox_issues_storage_access(((storage.foldername(name))[1])::uuid));;
